import json, re
beats=json.load(open('beats.json'))
STYLE=("2D digital cartoon illustration in the big-head stick-figure style: oversized semi-realistic caricature heads with fine wrinkle and feature linework and flat skin tones, attached to minimal thick solid-black stick-figure bodies with no hands and no clothing volume; highly detailed, period-accurate hand-drawn background with clean black ink outlines and flat muted colors; desaturated Elizabethan palette of oxblood, gold, chalk white, Tudor green, parchment beige, soot grey and black; deadpan dark-comedy tone; no gore, no visible wounds, blood or nudity; static 16:9 frame; bottom-right corner kept clear")
C={'BABY': 'you as a newborn baby girl, a tiny round head with a tuft of auburn hair', 'YOU5': 'you at age 5 (girl variant: a rounder oversized head about half her total height, auburn hair in two braids tied with oxblood bows, dozens of freckles across her nose and cheeks, lashes, bright wide eyes and a gap-toothed grin, __BONNET__on a short solid black stick body with no hands)', 'YOU8': 'you at age 8 (girl variant: a rounder oversized head about half her total height, auburn hair in two braids tied with oxblood bows, dozens of freckles across her nose and cheeks, lashes, bright wide eyes and a gap-toothed grin, __BONNET__on a short solid black stick body with no hands)', 'YOU16': 'you at 16 (adult woman variant, auburn-haired: a slimmer oval oversized head, auburn hair parted in the middle and gathered into a bun tied with an oxblood ribbon, lashes, half-lidded deadpan eyes, dozens of natural freckles across her nose and cheeks, tinted lips, bareheaded, on a solid black stick body with no hands)', 'YOUPAINT': 'you at 16 (adult woman variant, auburn-haired: a slimmer oval oversized head, auburn hair parted in the middle and gathered into a bun tied with an oxblood ribbon, lashes, half-lidded deadpan eyes, her whole face painted a smooth chalk white with bright red rouged cheeks and red lips, no freckles visible, bareheaded, on a solid black stick body with no hands)', 'YOUPAINT22': 'you at 22 (adult woman variant, auburn-haired: a slimmer oval oversized head, auburn hair parted in the middle and gathered into a bun tied with an oxblood ribbon, lashes, half-lidded deadpan eyes, her whole face painted a smooth chalk white with bright red rouged cheeks and red lips, no freckles visible, bareheaded, on a solid black stick body with no hands)', 'YOURUIN': 'you at 24 (adult woman variant, auburn-haired: a slimmer oval oversized head, auburn hair parted in the middle and gathered into a bun tied with an oxblood ribbon, lashes, half-lidded deadpan eyes, her unpainted face showing grey blotchy patches, small pits and scars and rough thin skin around the mouth, no freckles left, bareheaded, on a solid black stick body with no hands)', 'YOUPAINT40': 'you at 40 (adult woman variant, auburn-haired, older: a slimmer oval oversized head, auburn hair in a small bun, lashes, half-lidded deadpan eyes, thinning auburn hair streaked with grey, a thick slightly cracked chalk-white painted face with red rouge, lips pressed closed, bareheaded, on a solid black stick body with no hands)', 'YOURUIN40': 'you at 40 (adult woman variant, auburn-haired, older: a slimmer oval oversized head, auburn hair in a small bun, lashes, half-lidded deadpan eyes, thinning auburn hair streaked with grey, an unpainted grey scarred face and tired eyes, bareheaded, on a solid black stick body with no hands)', 'MOTHER': 'your mother (adult woman variant: a slimmer oval oversized head, dark brown hair parted in the middle and gathered into a bun tied with an oxblood ribbon, lashes, half-lidded deadpan eyes and tinted lips, on a solid black stick body with no hands)', 'MOTHERAGED': 'your mother, years older (adult woman variant, older: dark brown hair streaked with grey in a bun tied with an oxblood ribbon, deeper lines around the eyes and mouth, lashes and tinted lips, on a solid black stick body with no hands)', 'FATHER': 'your father, a quiet thin chandler with a gentle face, soot-smudged cheeks, receding brown hair and kind eyes, on a solid black stick body with no hands', 'COUNTESS': 'the Countess of Ashby, a haughty noblewoman with a chalk-white painted face, neck and chest, bright red rouged cheeks and lips, thin plucked arched brows, a high plucked hairline and fair hair in a jewelled updo, on a solid black stick body with no hands', 'COUNTESSOLD': 'the Countess of Ashby, older, with paint so thick it looks like cracked plaster, bright red rouge, thin plucked brows and a stiff curled red wig, on a solid black stick body with no hands', 'JOAN': 'Joan, a round-faced, sharp-eyed maid of about thirty from Kent, with a white painted face, red rouged cheeks, a cheeky grin and brown hair in a bun, on a solid black stick body with no hands', 'JOANSICK': 'Joan, now ill, with thinning brown hair, a grey blotchy face showing through patchy white paint, one blackened tooth and dark shadows under tired eyes, on a solid black stick body with no hands', 'ALICE': 'Alice, a nervous 15-year-old country maid (girl variant, older: a rounder oversized head, light brown braids, dozens of freckles, lashes and wide anxious eyes, on a solid black stick body with no hands)', 'STEWARD': 'a stiff steward with a neat grey beard, a starched white ruff and a superior expression, on a solid black stick body with no hands', 'APOTHECARY': "the apothecary (old man variant: an oversized head with a bald, lined crown, white side tufts above the ears, thick white brows, white mutton-chop whiskers, round spectacles, forehead lines and crow's feet, on a stooped solid black stick body with no hands)", 'PHYSICIAN': 'a pompous physician with a pointed black beard, a small white ruff and a confident smirk, on a solid black stick body with no hands', 'QUEENYOUNG': 'Queen Elizabeth I at 29, with a pale face, curled red hair and sharp dark eyes, on a solid black stick body with no hands', 'QUEEN': 'Queen Elizabeth I at 67, with a thick chalk-white mask of paint, bright red rouge, a towering bright orange curled wig threaded with pearls, a huge lace ruff and blackened teeth, on a solid black stick body with no hands'}
S={'cheapside': ('Cheapside in 1560s London, a crowded street of tall timber-framed houses, shop signs, market stalls, carts and church spires', 'flat even daylight, warm stone tint'), 'shop': ("a 1560s chandler's shop with racks of hanging candles, pots of melted tallow, a wooden workbench and smoke curling up", 'flat even ambient light, warm tallow-yellow tint'), 'home': ('a small family room above the shop with a stone fireplace, a sewing table by the window and wooden stools', 'flat even ambient light, warm firelight tint'), 'churchyard': ('a London churchyard with a low stone wall, old gravestones and a small church', 'flat even daylight, soft green tint'), 'queen1562': ('a royal bedchamber in 1562 with a curtained four-poster bed, tapestries and a dressing table', 'flat even ambient light, muted gold tint'), 'countess_ext': ('a grand Elizabethan mansion on the Strand with glittering glass windows and formal gardens running down to the Thames', 'flat even daylight, fresh green tint'), 'hall': ('a great hall in an Elizabethan mansion with long tables, tapestries and hundreds of candles', 'flat even ambient light, warm golden tint'), 'kitchen': ("a busy Elizabethan mansion kitchen with a big hearth, copper pots, pies and a servants' table", 'flat even ambient light, warm hearth tint'), 'maids_room': ("a small maids' bedroom with a shared bed, a candle, a little mirror and a chest of cosmetic pots", 'flat even ambient light, dim warm candle tint'), 'dressing': ("the Countess's dressing room with a large silver mirror and a dressing table crowded with pots of white paint, rouge, brushes and bottles", 'flat even ambient light, pale silver-cream tint'), 'apothecary': ('a cramped Elizabethan apothecary shop with shelves of strange bottles, jars, dried herbs and a mortar and pestle', 'flat even ambient light, murky green-amber tint'), 'dungheap': ('a muddy yard behind the apothecary with a steaming heap of horse dung, buried clay pots and lead sheets', 'flat even overcast daylight, muddy brown tint'), 'feast': ('a Twelfth Night feast in the great hall with garlands, candles, musicians and a large cake', 'flat even ambient light, warm golden tint'), 'dark_room': ('a dim sickroom with curtains drawn, a narrow bed, a basin and a single candle', 'flat even ambient light, dim cold grey tint'), 'whitehall': ('the throne room at Whitehall Palace in 1600 with a gold canopy, tapestries, courtiers and hundreds of candles', 'flat even ambient light, rich gold tint'), 'richmond': ('a quiet chamber at Richmond Palace in 1603 with cushions piled on the floor and heavy curtains', 'flat even ambient light, pale grey-gold tint'), 'rented_room': ('a small, sparse rented room near Cheapside with a narrow bed, a small mirror, a stool and a single tallow candle', 'flat even ambient light, dim warm tint'), 'street_spring': ('Cheapside on a bright spring morning with an orange seller, a dog, children on the churchyard wall and sunshine', 'flat even bright daylight, warm spring tint')}
OUTDOOR={'cheapside', 'countess_ext', 'churchyard', 'street_spring'}
BAD=set()
def variant(k,sc):
    d=C[k]
    if k in('YOU5','YOU8'):
        return d.replace('__BONNET__','under a plain white linen bonnet tied under the chin, ' if sc in OUTDOOR else '')
    return d
SHORT={'BABY':'you as a baby','YOU5':'you (age 5)','YOU8':'you (age 8)','YOU16':'you (age 16)','YOUPAINT':'you (painted)','YOUPAINT22':'you (painted, 22)','YOURUIN':'you (unpainted)','YOUPAINT40':'you (painted, 40)','YOURUIN40':'you (unpainted, 40)','MOTHER':'your mother','MOTHERAGED':'your mother','FATHER':'your father','COUNTESS':'the Countess','COUNTESSOLD':'the Countess','JOAN':'Joan','JOANSICK':'Joan','ALICE':'Alice','STEWARD':'the steward','APOTHECARY':'the apothecary','PHYSICIAN':'the physician','QUEENYOUNG':'the young Queen','QUEEN':'the Queen'}
CAM={'W':'Wide establishing shot, eye level','M':'Medium shot, eye level','C':'Close-up, eye level','ECU':'Extreme close-up','HA':'High-angle shot looking down','TD':'Top-down overhead shot','LA':'Low-angle shot looking up','POV':'First-person point-of-view shot','OTS':'Over-the-shoulder shot'}
fix={93:"dazed spiral eyes"}
rows=[]
for line in open('shots.txt'):
    if not line.strip(): continue
    n,sc,cam,mood,act=line.rstrip('\n').split('|',4)
    n=int(n)
    act=act.replace('with X-eyes for a moment','with dazed spiral eyes')
    import re
    a=re.sub(r'^(extreme close-up of|close-up of|high-angle view of|top-down view of|low-angle view of|wide view of|extreme detail on|a cutaway of)\s+','',act)
    for k in sorted(C,key=len,reverse=True): a=a.replace('{'+k+'}',variant(k,'indoor' if n in BAD else sc))
    short=act
    for k in C: short=short.replace('{'+k+'}',SHORT.get(k,k.lower()))
    env,light=S[sc]
    prompt=f"{CAM[cam]} of {a}. Setting: {env}. Lighting: {light}. Mood: {mood}. Style: {STYLE}."
    rows.append(dict(n=n,seg=beats[n-1],prompt=prompt,cam=CAM[cam],light=light,mood=mood,action=short[0].upper()+short[1:]))
assert [r['n'] for r in rows]==list(range(1,len(beats)+1)), "mismatch"
json.dump(rows,open('prompts.json','w'),indent=1)
with open('image_prompts.md','w') as f:
    f.write("# Why It Sucks to Want Clear Skin (in Elizabethan England) — Image Prompts\n\n311 beats · ~3–5 s each · Visual Style Profile locked · Characters locked to the Yesteryears character sheets\n\n"
  "**Headwear rule:** headwear fits the character's class and the scene. Nobody wears a hat indoors or in any bad scenario. As a girl outdoors, you wear the plain linen bonnet your mother ties each morning (the script calls for it); as an adult, you are always bareheaded. The only other caps are the two the script names: Joan pulling her cap lower, and you taking yours off before stepping into the sun.\n\n"
  "**Character lock**\n\n| Story role | Sheet |\n|---|---|\n| You, age 5 / 8 | Girl variant, with freckles |\n| You, 16 / 22 / 24 / 40 | Adult woman variant, auburn-haired (natural, painted and unpainted states) |\n| Your mother | Adult woman variant |\n| Alice | Girl variant, older |\n| The apothecary | Old man variant |\n"
  "| Father, the Countess, Joan, steward, physician, Queen Elizabeth | Not on a sheet (fixed descriptions) |\n\n")
    for r in rows:
        f.write(f"## Beat {r['n']}\n**[Script Segment]** \"{r['seg']}\"\n\n**Image Prompt:** {r['prompt']}\n\n- **Camera Angle:** {r['cam']}\n- **Lighting:** {r['light']}\n- **Mood:** {r['mood']}\n- **Action:** {r['action']}\n\n")
print(len(rows))
